SEED = 42
random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)
set_seed(SEED)
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
assert DEVICE.type == "cuda", "Select a GPU runtime for the full experiment."
# In Colab, persist outputs and checkpoints in the user's Google Drive.
